  38 | // ── Boot ──────────────────────────────────────────────────────────────────
  39 | window.addEventListener('DOMContentLoaded', async () => {
  40 |   applyStoredTheme();
  41 |   await loadSectors();
  42 |   await loadStocks();
  43 | });
