 131 | // ── Re-render (sort only) ─────────────────────────────────────────────────
 132 | function reRender() {
 133 |   const sortKey = document.getElementById('sort-select').value;
 134 |   const n       = parseInt(document.getElementById('top-n').value, 10);
 135 | 
 136 |   const sorted  = [...stockData].sort((a, b) => {
 137 |     if (sortKey === 'score')    return b.score    - a.score;
 138 |     if (sortKey === 'change1d') return b.change1d - a.change1d;
 139 |     if (sortKey === 'pe')       return (a.pe ?? 9999) - (b.pe ?? 9999);
 140 |     if (sortKey === 'rsi')      return a.rsi - b.rsi;
 141 |     return 0;
 142 |   }).slice(0, n);
 143 | 
 144 |   const grid = document.getElementById('cards-grid');
 145 |   grid.innerHTML = '';
 146 |   sorted.forEach((s, i) => {
 147 |     const card = buildCard(s, i + 1);
 148 |     // Staggered slide-in: each card gets a delayed entry animation
 149 |     card.style.animationDelay = `${i * 55}ms`;
 150 |     card.classList.add('card-enter');
 151 |     grid.appendChild(card);
 152 |   });
 153 |   grid.classList.remove('hidden');
 154 | 
 155 |   // show the column header row
 156 |   document.getElementById('table-head').classList.remove('hidden');
 157 | 
 158 |   requestAnimationFrame(() => sorted.forEach(s => drawSparkline(s)));
 159 | }
