 161 | // ── Build a compact table-row card ───────────────────────────────────────
 162 | function buildCard(s, rank) {
 163 |   const card = document.createElement('div');
 164 |   card.className = 'card';
 165 |   card.dataset.ticker = s.ticker;
 166 |   card.addEventListener('click', () => {
 167 |     if (Math.random() < 0.5) {
 168 |       openModal(s);
 169 |     } else {
 170 |       rejectClick(card, s.ticker);
 171 |     }
 172 |   });
 173 | 
 174 |   const scoreClass = s.score >= 72 ? 'high' : s.score >= 55 ? 'medium' : 'low';
 175 |   const chgClass   = s.change1d > 0 ? 'pos' : s.change1d < 0 ? 'neg' : 'neu';
 176 |   const chgSign    = s.change1d > 0 ? '+' : '';
 177 |   const medals     = ['🥇','🥈','🥉'];
 178 |   const rankLabel  = rank <= 3 ? medals[rank - 1] : `#${rank}`;
 179 | 
 180 |   card.innerHTML = `
 181 |     <div class="row-rank ${rank<=3?'top3':''}">${rankLabel}</div>
 182 |     <div class="row-spark"><canvas id="spark-${s.ticker}"></canvas></div>
 183 |     <div class="row-ticker">
 184 |       <a class="row-ticker-sym yf-link" href="https://finance.yahoo.com/quote/${s.ticker}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${s.ticker} ↗</a>
 185 |       <span class="row-ticker-name">${s.name}</span>
 186 |     </div>
 187 |     <div class="row-price">$${s.currentPrice.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</div>
 188 |     <div class="row-chg"><span class="chg ${chgClass}">${chgSign}${s.change1d.toFixed(2)}%</span></div>
 189 |     <div class="row-score"><span class="score-val ${scoreClass}">${s.score}</span></div>
 190 |     <div class="row-pe">${s.pe ?? '—'}</div>
 191 |     <div class="row-rsi">${s.rsi}</div>
 192 |     <div class="row-eps">${s.epsGrowth != null ? s.epsGrowth + '%' : '—'}</div>
 193 |     <div class="row-margin">${s.profitMargin != null ? s.profitMargin + '%' : '—'}</div>
 194 |     <div class="row-cap">${formatMktCap(s.marketCap)}</div>`;
 195 | 
 196 |   return card;
