 199 | // ── Sparkline (pure canvas, compact 36 px tall) ───────────────────────────
 200 | function drawSparkline(s) {
 201 |   const canvas = document.getElementById(`spark-${s.ticker}`);
 202 |   if (!canvas || !s.sparkline || s.sparkline.length < 2) return;
 203 | 
 204 |   const dpr = window.devicePixelRatio || 1;
 205 |   const w   = canvas.parentElement.clientWidth - 8; // subtract padding
 206 |   const h   = 36;
 207 |   canvas.width  = w * dpr;
 208 |   canvas.height = h * dpr;
 209 |   canvas.style.width  = w + 'px';
 210 |   canvas.style.height = h + 'px';
 211 |   const ctx = canvas.getContext('2d');
 212 |   ctx.scale(dpr, dpr);
 213 | 
 214 |   const prices = s.sparkline;
 215 |   const min    = Math.min(...prices);
 216 |   const max    = Math.max(...prices);
 217 |   const range  = max - min || 1;
 218 |   const pad    = 2;
 219 |   const xFn    = i => (i / (prices.length - 1)) * (w - pad * 2) + pad;
 220 |   const yFn    = v => h - pad - ((v - min) / range) * (h - pad * 2);
 221 | 
 222 |   const isUp = prices[prices.length - 1] >= prices[0];
 223 |   const col  = isUp ? '63,185,80' : '248,81,73';
 224 |   const grad = ctx.createLinearGradient(0, 0, 0, h);
 225 |   grad.addColorStop(0, `rgba(${col},.25)`);
 226 |   grad.addColorStop(1, `rgba(${col},0)`);
 227 | 
 228 |   // filled area
 229 |   ctx.beginPath();
 230 |   ctx.moveTo(xFn(0), yFn(prices[0]));
 231 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
 232 |   ctx.lineTo(xFn(prices.length - 1), h);
 233 |   ctx.lineTo(xFn(0), h);
 234 |   ctx.closePath();
 235 |   ctx.fillStyle = grad;
 236 |   ctx.fill();
 237 | 
 238 |   // line
 239 |   ctx.beginPath();
 240 |   ctx.moveTo(xFn(0), yFn(prices[0]));
 241 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
 242 |   ctx.strokeStyle = `rgb(${col})`;
 243 |   ctx.lineWidth   = 1.5;
 244 |   ctx.lineJoin    = 'round';
 245 |   ctx.stroke();
 246 | }
