 339 | // ── Utilities ─────────────────────────────────────────────────────────────
 340 | function formatMktCap(cap) {
 341 |   if (!cap) return '—';
 342 |   if (cap >= 1e12) return `$${(cap/1e12).toFixed(1)}T`;
 343 |   if (cap >= 1e9)  return `$${(cap/1e9).toFixed(1)}B`;
 344 |   if (cap >= 1e6)  return `$${(cap/1e6).toFixed(1)}M`;
 345 |   return `$${cap}`;
 346 | }
