 669 | // ── Floating button physics ────────────────────────────────────────────────
 670 | let _floatX = 0, _floatY = 0;       // current position (px)
 671 | let _floatVX = 2.2, _floatVY = 1.7; // velocity (px per frame)
 672 | let _floatAngle = 0;                 // current rotation (deg)
 673 | let _floatSpin  = 1.8;               // rotation speed (deg per frame)
 674 | let _floatT     = 0;                 // time counter for opacity sine wave
 675 | let _floatRafId  = null;
 676 | let _floatPaused = false;
 677 | 
 678 | function _floatLoop() {
 679 |   const btn = document.getElementById('random-ticker-btn');
 680 |   if (!btn) return;
 681 | 
 682 |   if (!_floatPaused) {
 683 |     const bw = btn.offsetWidth  || 90;
 684 |     const bh = btn.offsetHeight || 26;
 685 |     const maxX = window.innerWidth  - bw;
 686 |     const maxY = window.innerHeight - bh;
 687 | 
 688 |     _floatX += _floatVX;
 689 |     _floatY += _floatVY;
 690 | 
 691 |     // Bounce off edges
 692 |     if (_floatX <= 0)    { _floatX = 0;    _floatVX = Math.abs(_floatVX); }
 693 |     if (_floatX >= maxX) { _floatX = maxX; _floatVX = -Math.abs(_floatVX); }
 694 |     if (_floatY <= 0)    { _floatY = 0;    _floatVY = Math.abs(_floatVY); }
 695 |     if (_floatY >= maxY) { _floatY = maxY; _floatVY = -Math.abs(_floatVY); }
 696 | 
 697 |     _floatAngle += _floatSpin;
 698 |     _floatT     += 0.025;  // sine wave speed — lower = slower fade
 699 | 
 700 |     const opacity = 0.3 + 0.7 * (Math.sin(_floatT) * 0.5 + 0.5);
 701 | 
 702 |     btn.style.left      = _floatX + 'px';
 703 |     btn.style.top       = _floatY + 'px';
 704 |     btn.style.transform = `rotate(${_floatAngle}deg)`;
 705 |     btn.style.opacity   = opacity;
 706 |   }
 707 | 
 708 |   _floatRafId = requestAnimationFrame(_floatLoop);
 709 | }
 710 | 
 711 | // Randomly pause for 0.8–2.5 s, then resume in a new direction; repeats every 4–10 s
 712 | function _scheduleNextPause() {
 713 |   const delay    = 4000 + Math.random() * 6000;   // wait 4–10 s before pausing
 714 |   const duration = 800  + Math.random() * 1700;   // stay paused 0.8–2.5 s
 715 |   setTimeout(() => {
 716 |     _floatPaused = true;
 717 |     setTimeout(() => {
 718 |       // Pick a fresh random direction at the same speed
 719 |       const angle = Math.random() * 2 * Math.PI;
 720 |       const speed = 2.5;
 721 |       _floatVX = Math.cos(angle) * speed;
 722 |       _floatVY = Math.sin(angle) * speed;
 723 |       // Pick a new random spin speed (1–3 deg/frame, random direction)
 724 |       _floatSpin = (1 + Math.random() * 2) * (Math.random() < 0.5 ? 1 : -1);
 725 |       _floatPaused = false;
 726 |       _scheduleNextPause();
 727 |     }, duration);
 728 |   }, delay);
 729 | }
 730 | 
 731 | function startFloatingBtn() {
 732 |   const btn = document.getElementById('random-ticker-btn');
 733 |   if (!btn) return;
 734 |   // Random starting position
 735 |   _floatX = Math.random() * (window.innerWidth  - (btn.offsetWidth  || 90));
 736 |   _floatY = Math.random() * (window.innerHeight - (btn.offsetHeight || 26));
 737 |   // Random direction, consistent speed
 738 |   const angle = Math.random() * 2 * Math.PI;
 739 |   const speed = 2.5;
 740 |   _floatVX = Math.cos(angle) * speed;
 741 |   _floatVY = Math.sin(angle) * speed;
 742 |   _floatRafId = requestAnimationFrame(_floatLoop);
 743 |   _scheduleNextPause();
 744 | }
