/* ── Stock row (compact table-style card) ── */
.card {
  display: grid;
  grid-template-columns:
    var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
    var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
    var(--c-eps) var(--c-margin) var(--c-cap);
  align-items: center;
  padding: 0 10px;
  height: 44px;
  background: color-mix(in srgb, hsl(var(--card-hue, 220) 60% 18%) 22%, var(--bg2));
  border: 1px solid hsl(var(--card-hue, 220) 55% 38%);
  border-left: 3px solid hsl(var(--card-hue, 220) 80% 58%);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background .18s, border-color .18s, transform .18s cubic-bezier(0.34,1.56,0.64,1), box-shadow .18s;
  will-change: transform;
}
.card:hover {
  background: color-mix(in srgb, hsl(var(--card-hue, 220) 70% 28%) 35%, var(--bg3));
  border-color: hsl(var(--card-hue, 220) 90% 68%);
  border-left-color: hsl(var(--card-hue, 220) 90% 72%);
  transform: translateX(4px) scale(1.012);
  box-shadow: -3px 0 0 0 hsl(var(--card-hue, 220) 80% 58%), 0 6px 24px hsl(var(--card-hue, 220) 70% 50% / .2);
  z-index: 1;
  position: relative;
}

body.light .card {
  background: color-mix(in srgb, hsl(var(--card-hue, 220) 80% 60%) 10%, var(--bg2));
  border-color: hsl(var(--card-hue, 220) 55% 68%);
  border-left-color: hsl(var(--card-hue, 220) 70% 50%);
}
body.light .card:hover {
  background: color-mix(in srgb, hsl(var(--card-hue, 220) 80% 60%) 18%, var(--bg3));
  border-color: hsl(var(--card-hue, 220) 70% 45%);
  box-shadow: -3px 0 0 0 hsl(var(--card-hue, 220) 70% 50%), 0 6px 24px hsl(var(--card-hue, 220) 60% 50% / .18);
}

